<script>
	// toolSearch.js is only needed once the user actually focuses a search field, not on every page
	// that happens to render a .toolSelectSearch block -- deferred like tippy/popper/sortable below.
	pdf24.requireToolSearch = function(callback) {
		return utilz.requireScript({
			loadCheck: function() {
				return window.pdf24 && pdf24.toolSearch;
			},
			callback: callback,
			script: {
				id: 'toolSearchScript',
				src: '/static/js/toolSearch.js?v=6ac63c12'
			}
		});
	};

	// Shared across every .toolSelectSearch instance on the page (home, bottomToolSelect, and the
	// burger-cloned topToolSelect), so the sitemap is only fetched once no matter how many search
	// boxes exist.
	pdf24.loadToolSelectSearchPages = function() {
		if(!pdf24.toolSelectSearchPagesPromise) {
			pdf24.toolSelectSearchPagesPromise = $.getJSON('/en/tool-search.json').then(function(data) {
				pdf24.toolSelectSearchPages = data.pages || [];
				return pdf24.toolSelectSearchPages;
			});
			// allow a retry on the next focus/search instead of caching the failure
			pdf24.toolSelectSearchPagesPromise.fail(function() {
				pdf24.toolSelectSearchPagesPromise = null;
			});
		}
		return pdf24.toolSelectSearchPagesPromise;
	};

	// Wires one .toolSelectSearch instance up. Called on page load for the instances rendered by the
